"""dm-local transport for quyet 1.0.0; native readout is unchanged."""
import json
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
sys.path.insert(0, sys.argv[1] + "/src")
import quyet
from quyet.errors import QuestionError
if quyet.__version__ != "1.0.0":
    raise RuntimeError("expected quyet 1.0.0")
model = quyet.load(sys.argv[2], device=sys.argv[3])
for _ in range(3):
    model.predict("warm-up", {"decision": {"type": "noul", "instructions": "Is this a warm-up?", "criteria": {"true": "yes", "false": "no"}}})
class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass
    def send(self, status, body):
        raw = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)
    def do_GET(self):
        self.send(200, {"status": "ready"}) if self.path == "/health" else self.send(404, {"detail": "not found"})
    def do_POST(self):
        if self.path != "/v1/systemone":
            return self.send(404, {"detail": "not found"})
        try:
            body = json.loads(self.rfile.read(int(self.headers.get("Content-Length", "0"))))
            state, questions = body["state"], body["questions"]
        except (ValueError, TypeError, KeyError) as exc:
            return self.send(422, {"detail": str(exc)[:300]})
        try:
            out = model.predict(state, questions)
        except QuestionError as exc:
            return self.send(422, {"detail": str(exc)[:300]})
        except Exception as exc:
            return self.send(500, {"detail": type(exc).__name__})
        self.send(200, out)
assert sys.argv[5] == "127.0.0.1"
HTTPServer((sys.argv[5], int(sys.argv[4])), Handler).serve_forever()

